<?php
declare(strict_types=1);
/** ShahkotPK v10.2.0 Visitor Growth & Engagement Suite. First-party, tenant-scoped engagement helpers. */

function sk1020_table_exists(string $table): bool { static $c=[]; if(isset($c[$table]))return $c[$table]; if(!preg_match('/^[A-Za-z][A-Za-z0-9_]{0,63}$/',$table))return false; try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1');$q->execute([$table]);return $c[$table]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$table]=false;} }
function sk1020_columns(string $table): array { static $c=[];if(isset($c[$table]))return $c[$table];if(!sk1020_table_exists($table))return $c[$table]=[];try{$q=db()->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$q->execute([$table]);return $c[$table]=array_map('strval',$q->fetchAll(PDO::FETCH_COLUMN));}catch(Throwable $e){return $c[$table]=[];} }
function sk1020_tenant_id(): int { try{if(function_exists('tenant_id'))return max(0,(int)tenant_id());if(function_exists('current_tenant')){$t=current_tenant();return max(0,(int)($t['id']??0));}}catch(Throwable $e){}return 0; }
function sk1020_user_id(): int { try{if(function_exists('current_user')){$u=current_user();return max(0,(int)($u['id']??0));}}catch(Throwable $e){}return 0; }
function sk1020_visitor_key(): string { static $key='';if($key!=='')return $key;$raw=(string)($_COOKIE['sk1020_visitor']??'');if(!preg_match('/^[a-f0-9]{40}$/',$raw)){$raw=bin2hex(random_bytes(20));if(!headers_sent())setcookie('sk1020_visitor',$raw,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);}$key=hash('sha256',$raw);return $key; }
function sk1020_session_key(): string { $s=session_id();return $s!==''?hash('sha256',$s):hash('sha256',sk1020_visitor_key().date('Y-m-d')); }
function sk1020_settings(int $tenantId=-1,bool $refresh=false): array { static $cache=[];$tenantId=$tenantId<0?sk1020_tenant_id():$tenantId;if(!$refresh&&isset($cache[$tenantId]))return $cache[$tenantId];$d=['tenant_id'=>$tenantId,'personalization_enabled'=>1,'trending_enabled'=>1,'near_you_enabled'=>1,'deals_enabled'=>1,'rewards_enabled'=>1,'referral_enabled'=>1,'favorites_enabled'=>1,'follow_enabled'=>1,'alerts_enabled'=>1,'share_enabled'=>1,'compare_enabled'=>1,'voice_search_enabled'=>1,'community_enabled'=>1,'campaigns_enabled'=>1,'analytics_enabled'=>1,'pwa_prompt_enabled'=>1,'return_visitor_enabled'=>1,'guest_sync_enabled'=>1,'seo_enabled'=>1,'ab_testing_enabled'=>0,'points_welcome'=>50,'points_daily'=>5,'points_referral'=>100,'points_share'=>2,'hero_b_heading'=>'','hero_b_subtitle'=>''];if(!sk1020_table_exists('growth_settings_v1020'))return $cache[$tenantId]=$d;try{$q=db()->prepare('SELECT * FROM growth_settings_v1020 WHERE tenant_id=? LIMIT 1');$q->execute([$tenantId]);$r=$q->fetch();if(!$r){db()->prepare('INSERT IGNORE INTO growth_settings_v1020(tenant_id) VALUES(?)')->execute([$tenantId]);$r=[];}return $cache[$tenantId]=array_merge($d,$r?:[]);}catch(Throwable $e){return $cache[$tenantId]=$d;} }
function sk1020_feature(string $key,int $tenantId=-1): bool {$s=sk1020_settings($tenantId);$k=$key.'_enabled';return !array_key_exists($k,$s)||(int)$s[$k]===1;}
function sk1020_json($v): string {return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}
function sk1020_value(array $row,array $keys,$default=''){foreach($keys as $k)if(isset($row[$k])&&$row[$k]!==''&&$row[$k]!==null)return $row[$k];return $default;}
function sk1020_title(array $r): string{return (string)sk1020_value($r,['title','title_en','name','headline','subject'],'Untitled');}
function sk1020_image(array $r): string{return (string)sk1020_value($r,['image_url','image','thumbnail_url','thumbnail','cover_url','cover_image','featured_image','card_image','banner_url','logo_url'],'');}
function sk1020_entity_map(string $type): ?array { $m=['business'=>['businesses','/business.php?id='], 'product'=>['store_products','/product.php?id='], 'property'=>['city_portal_items','/property.php?id=',['content_type'=>'property']], 'news'=>['news_posts','/news.php?id='], 'job'=>['city_portal_items','/jobs.php?id=',['content_type'=>'job']], 'event'=>['city_portal_items','/events.php?id=',['content_type'=>'event']], 'doctor'=>['health_doctors_v580','/doctor-online.php?id=']];return $m[$type]??null; }
function sk1020_fetch_entity(string $type,int $id,int $tenantId=-1): array { $map=sk1020_entity_map($type);if(!$map||$id<1||!sk1020_table_exists($map[0]))return [];$tenantId=$tenantId<0?sk1020_tenant_id():$tenantId;$cols=sk1020_columns($map[0]);$w=['id=?'];$p=[$id];if($tenantId>0&&in_array('tenant_id',$cols,true)){$w[]='tenant_id=?';$p[]=$tenantId;}foreach(($map[2]??[]) as $k=>$v)if(in_array($k,$cols,true)){$w[]="`$k`=?";$p[]=$v;}try{$q=db()->prepare('SELECT * FROM `'.$map[0].'` WHERE '.implode(' AND ',$w).' LIMIT 1');$q->execute($p);$r=$q->fetch()?:[];if($r){$r['_entity_type']=$type;$r['_url']=$map[1].$id;}return $r;}catch(Throwable $e){return [];} }
function sk1020_log(string $event,string $entityType='',int $entityId=0,array $meta=[],?string $query=null,?int $resultCount=null): void { if(!sk1020_feature('analytics')||!sk1020_table_exists('visitor_events_v1020'))return;$event=substr(preg_replace('/[^a-z0-9_.-]/i','',$event),0,48);if($event==='')return;try{$q=db()->prepare('INSERT INTO visitor_events_v1020(tenant_id,visitor_key,user_id,session_key,event_type,entity_type,entity_id,search_query,result_count,url,referrer,meta_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([sk1020_tenant_id(),sk1020_visitor_key(),sk1020_user_id(),sk1020_session_key(),$event,substr($entityType,0,40),max(0,$entityId),$query!==null?mb_substr($query,0,255):null,$resultCount,mb_substr((string)($_SERVER['REQUEST_URI']??''),0,500),mb_substr((string)($_SERVER['HTTP_REFERER']??''),0,500),$meta?sk1020_json($meta):null]);}catch(Throwable $e){} }
function sk1020_rate_ok(string $action,int $limit=45,int $seconds=60): bool {if(!sk1020_table_exists('visitor_events_v1020'))return true;try{$cutoff=date('Y-m-d H:i:s',time()-max(1,$seconds));$q=db()->prepare('SELECT COUNT(*) FROM visitor_events_v1020 WHERE tenant_id=? AND visitor_key=? AND event_type=? AND created_at>=?');$q->execute([sk1020_tenant_id(),sk1020_visitor_key(),'api.'.$action,$cutoff]);return (int)$q->fetchColumn()<$limit;}catch(Throwable $e){return true;} }
function sk1020_recent_touch(string $type,int $id): void {if(!sk1020_feature('personalization')||!sk1020_table_exists('visitor_recent_v1020')||!sk1020_entity_map($type)||$id<1)return;try{db()->prepare('INSERT INTO visitor_recent_v1020(tenant_id,visitor_key,user_id,entity_type,entity_id,view_count,last_viewed_at) VALUES(?,?,?,?,?,1,NOW()) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id),view_count=view_count+1,last_viewed_at=NOW()')->execute([sk1020_tenant_id(),sk1020_visitor_key(),sk1020_user_id(),$type,$id]);}catch(Throwable $e){} }
function sk1020_recent_items(int $limit=8): array {if(!sk1020_table_exists('visitor_recent_v1020'))return [];$out=[];try{$uid=sk1020_user_id();if($uid>0){$q=db()->prepare('SELECT entity_type,entity_id,MAX(last_viewed_at) lv FROM visitor_recent_v1020 WHERE tenant_id=? AND (visitor_key=? OR user_id=?) GROUP BY entity_type,entity_id ORDER BY lv DESC LIMIT '.max(1,min(24,$limit)));$q->execute([sk1020_tenant_id(),sk1020_visitor_key(),$uid]);}else{$q=db()->prepare('SELECT entity_type,entity_id FROM visitor_recent_v1020 WHERE tenant_id=? AND visitor_key=? ORDER BY last_viewed_at DESC LIMIT '.max(1,min(24,$limit)));$q->execute([sk1020_tenant_id(),sk1020_visitor_key()]);}foreach($q->fetchAll() as $x){$r=sk1020_fetch_entity((string)$x['entity_type'],(int)$x['entity_id']);if($r)$out[]=$r;}}catch(Throwable $e){}return $out; }
function sk1020_trending(int $limit=8): array {if(!sk1020_table_exists('visitor_events_v1020'))return [];$out=[];try{$q=db()->prepare("SELECT entity_type,entity_id,COUNT(*) score FROM visitor_events_v1020 WHERE tenant_id=? AND entity_id>0 AND entity_type<>'' AND created_at>=DATE_SUB(NOW(),INTERVAL 7 DAY) AND event_type IN ('view','card_click','favorite','share') GROUP BY entity_type,entity_id ORDER BY score DESC LIMIT ".max(1,min(30,$limit*3)));$q->execute([sk1020_tenant_id()]);foreach($q->fetchAll() as $x){$r=sk1020_fetch_entity((string)$x['entity_type'],(int)$x['entity_id']);if($r){$r['_score']=(int)$x['score'];$out[]=$r;if(count($out)>=$limit)break;}}}catch(Throwable $e){}return $out; }
function sk1020_mixed_latest(int $limit=8): array { $out=[];foreach([['business','businesses'],['product','store_products'],['news','news_posts'],['event','city_portal_items']] as [$type,$table]){if(!sk1020_table_exists($table))continue;$cols=sk1020_columns($table);$w=[];$p=[];$tid=sk1020_tenant_id();if($tid>0&&in_array('tenant_id',$cols,true)){$w[]='tenant_id=?';$p[]=$tid;}if($type==='event'&&in_array('content_type',$cols,true)){$w[]='content_type=?';$p[]='event';}try{$q=db()->prepare('SELECT * FROM `'.$table.'`'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY id DESC LIMIT '.max(1,(int)ceil($limit/4)));$q->execute($p);foreach($q->fetchAll() as $r){$r['_entity_type']=$type;$r['_url']=(sk1020_entity_map($type)[1]??'#').(int)($r['id']??0);$out[]=$r;}}catch(Throwable $e){}}usort($out,fn($a,$b)=>(int)($b['id']??0)<=>(int)($a['id']??0));return array_slice($out,0,$limit); }
function sk1020_campaign(): array {if(!sk1020_feature('campaigns')||!sk1020_table_exists('growth_campaigns_v1020'))return [];$uid=sk1020_user_id();try{$q=db()->prepare("SELECT * FROM growth_campaigns_v1020 WHERE tenant_id=? AND status='active' AND (starts_at IS NULL OR starts_at<=NOW()) AND (ends_at IS NULL OR ends_at>=NOW()) AND audience IN ('all',?) ORDER BY id DESC LIMIT 1");$q->execute([sk1020_tenant_id(),$uid>0?'member':'guest']);$r=$q->fetch()?:[];if($r)db()->prepare('UPDATE growth_campaigns_v1020 SET impressions=impressions+1 WHERE id=?')->execute([(int)$r['id']]);return $r;}catch(Throwable $e){return [];} }
function sk1020_is_returning(): bool {if(!sk1020_table_exists('visitor_events_v1020'))return false;try{$q=db()->prepare('SELECT COUNT(*) FROM visitor_events_v1020 WHERE tenant_id=? AND visitor_key=? AND created_at<DATE_SUB(NOW(),INTERVAL 30 MINUTE)');$q->execute([sk1020_tenant_id(),sk1020_visitor_key()]);return (int)$q->fetchColumn()>0;}catch(Throwable $e){return false;} }
function sk1020_reward_account(int $userId): array {if($userId<1||!sk1020_table_exists('growth_rewards_accounts_v1020'))return [];try{$tid=sk1020_tenant_id();$i=db()->prepare('INSERT IGNORE INTO growth_rewards_accounts_v1020(tenant_id,user_id) VALUES(?,?)');$i->execute([$tid,$userId]);if($i->rowCount()>0){$pts=max(0,(int)sk1020_settings($tid)['points_welcome']);if($pts>0){db()->prepare('INSERT INTO growth_rewards_ledger_v1020(tenant_id,user_id,event_key,points,reference_key,note) VALUES(?,?,?,?,?,?)')->execute([$tid,$userId,'welcome',$pts,'welcome-account','Welcome to ShahkotPK Rewards']);db()->prepare('UPDATE growth_rewards_accounts_v1020 SET points_balance=?,lifetime_points=? WHERE tenant_id=? AND user_id=?')->execute([$pts,$pts,$tid,$userId]);}}$q=db()->prepare('SELECT * FROM growth_rewards_accounts_v1020 WHERE tenant_id=? AND user_id=? LIMIT 1');$q->execute([$tid,$userId]);return $q->fetch()?:[];}catch(Throwable $e){return [];} }
function sk1020_award(int $userId,string $event,int $points,string $ref='',string $note=''): bool {if($userId<1||$points===0||!sk1020_feature('rewards')||!sk1020_table_exists('growth_rewards_ledger_v1020'))return false;$tid=sk1020_tenant_id();try{if($ref!==''){$q=db()->prepare('SELECT 1 FROM growth_rewards_ledger_v1020 WHERE tenant_id=? AND user_id=? AND event_key=? AND reference_key=? LIMIT 1');$q->execute([$tid,$userId,$event,$ref]);if($q->fetchColumn())return false;}db()->beginTransaction();db()->prepare('INSERT IGNORE INTO growth_rewards_accounts_v1020(tenant_id,user_id) VALUES(?,?)')->execute([$tid,$userId]);db()->prepare('INSERT INTO growth_rewards_ledger_v1020(tenant_id,user_id,event_key,points,reference_key,note) VALUES(?,?,?,?,?,?)')->execute([$tid,$userId,substr($event,0,48),$points,$ref!==''?substr($ref,0,190):null,mb_substr($note,0,500)]);db()->prepare('UPDATE growth_rewards_accounts_v1020 SET points_balance=GREATEST(0,points_balance+?),lifetime_points=lifetime_points+GREATEST(?,0) WHERE tenant_id=? AND user_id=?')->execute([$points,$points,$tid,$userId]);db()->commit();return true;}catch(Throwable $e){try{if(db()->inTransaction())db()->rollBack();}catch(Throwable $x){}return false;} }
function sk1020_checkin(int $userId): array {$s=sk1020_settings();$acc=sk1020_reward_account($userId);if(!$acc)return ['ok'=>false,'message'=>'Sign in to use Daily Check-in.'];$today=date('Y-m-d');if((string)($acc['last_checkin_date']??'')===$today)return ['ok'=>true,'already'=>true,'message'=>'Today’s check-in is already complete.','account'=>$acc];$yesterday=date('Y-m-d',strtotime('-1 day'));$streak=(string)($acc['last_checkin_date']??'')===$yesterday?((int)$acc['streak_days']+1):1;$points=max(0,(int)$s['points_daily']);try{db()->prepare('UPDATE growth_rewards_accounts_v1020 SET streak_days=?,last_checkin_date=? WHERE tenant_id=? AND user_id=?')->execute([$streak,$today,sk1020_tenant_id(),$userId]);sk1020_award($userId,'daily_checkin',$points,'checkin:'.$today,'Daily visitor check-in');$acc=sk1020_reward_account($userId);return ['ok'=>true,'message'=>'Check-in complete. +'.$points.' points.','account'=>$acc];}catch(Throwable $e){return ['ok'=>false,'message'=>'Could not complete check-in.'];} }
function sk1020_referral_code(int $userId): string {if($userId<1||!sk1020_table_exists('growth_referral_codes_v1020'))return '';try{$q=db()->prepare('SELECT referral_code FROM growth_referral_codes_v1020 WHERE tenant_id=? AND user_id=? LIMIT 1');$q->execute([sk1020_tenant_id(),$userId]);$c=(string)($q->fetchColumn()?:'');if($c!=='')return $c;for($i=0;$i<5;$i++){$c='SK'.strtoupper(base_convert((string)$userId,10,36)).strtoupper(substr(bin2hex(random_bytes(4)),0,6));try{db()->prepare('INSERT INTO growth_referral_codes_v1020(tenant_id,user_id,referral_code) VALUES(?,?,?)')->execute([sk1020_tenant_id(),$userId,$c]);return $c;}catch(Throwable $x){}}}catch(Throwable $e){}return ''; }
function sk1020_capture_referral(): void {if(!sk1020_feature('referral')||!sk1020_table_exists('growth_referral_codes_v1020'))return;$ref=strtoupper(trim((string)($_GET['ref']??'')));if($ref!==''&&preg_match('/^[A-Z0-9]{4,40}$/',$ref)){try{$q=db()->prepare('SELECT user_id FROM growth_referral_codes_v1020 WHERE tenant_id=? AND referral_code=? LIMIT 1');$q->execute([sk1020_tenant_id(),$ref]);$uid=(int)($q->fetchColumn()?:0);if($uid>0){if(!headers_sent())setcookie('sk1020_ref',$ref,['expires'=>time()+2592000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);db()->prepare('UPDATE growth_referral_codes_v1020 SET clicks=clicks+1 WHERE tenant_id=? AND referral_code=?')->execute([sk1020_tenant_id(),$ref]);db()->prepare('INSERT INTO growth_referral_events_v1020(tenant_id,referral_code,referrer_user_id,visitor_key,event_type) VALUES(?,?,?,?,?)')->execute([sk1020_tenant_id(),$ref,$uid,sk1020_visitor_key(),'click']);}}catch(Throwable $e){}} }
function sk1020_sync_guest_to_user(): void {$uid=sk1020_user_id();if($uid<1)return;if(session_status()===PHP_SESSION_ACTIVE&&!empty($_SESSION['sk1020_guest_synced']))return;$tid=sk1020_tenant_id();$vk=sk1020_visitor_key();foreach(['visitor_favorites_v1020','visitor_follows_v1020','visitor_recent_v1020','growth_saved_searches_v1020','growth_alerts_v1020'] as $t){if(!sk1020_table_exists($t))continue;try{db()->prepare('UPDATE `'.$t.'` SET user_id=? WHERE tenant_id=? AND visitor_key=? AND user_id=0')->execute([$uid,$tid,$vk]);}catch(Throwable $e){}}if(session_status()===PHP_SESSION_ACTIVE)$_SESSION['sk1020_guest_synced']=1;}
function sk1020_claim_referral_if_needed(): void {$uid=sk1020_user_id();$ref=strtoupper((string)($_COOKIE['sk1020_ref']??''));if($uid<1||$ref===''||!sk1020_feature('referral')||!sk1020_table_exists('growth_referral_events_v1020'))return;try{$q=db()->prepare('SELECT user_id FROM growth_referral_codes_v1020 WHERE tenant_id=? AND referral_code=? LIMIT 1');$q->execute([sk1020_tenant_id(),$ref]);$referrer=(int)($q->fetchColumn()?:0);if($referrer<1||$referrer===$uid)return;$q=db()->prepare("SELECT 1 FROM growth_referral_events_v1020 WHERE tenant_id=? AND referred_user_id=? AND event_type='conversion' LIMIT 1");$q->execute([sk1020_tenant_id(),$uid]);if($q->fetchColumn())return;$pts=max(0,(int)sk1020_settings()['points_referral']);db()->prepare("INSERT INTO growth_referral_events_v1020(tenant_id,referral_code,referrer_user_id,referred_user_id,visitor_key,event_type,points_awarded) VALUES(?,?,?,?,?,'conversion',?)")->execute([sk1020_tenant_id(),$ref,$referrer,$uid,sk1020_visitor_key(),$pts]);db()->prepare('UPDATE growth_referral_codes_v1020 SET conversions=conversions+1 WHERE tenant_id=? AND referral_code=?')->execute([sk1020_tenant_id(),$ref]);sk1020_award($referrer,'referral_conversion',$pts,'referred:'.$uid,'Successful referral');sk1020_award($uid,'referral_join',max(1,(int)floor($pts/2)),'referrer:'.$referrer,'Joined through referral');if(!headers_sent())setcookie('sk1020_ref','',['expires'=>time()-3600,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);}catch(Throwable $e){} }
function sk1020_ab_variant(): string {if(!sk1020_feature('ab_testing'))return 'A';$v=(string)($_COOKIE['sk1020_ab']??'');if(!in_array($v,['A','B'],true)){$v=random_int(0,1)?'B':'A';if(!headers_sent())setcookie('sk1020_ab',$v,['expires'=>time()+2592000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);}return $v; }
function sk1020_notifications(int $limit=8): array {if(!sk1020_table_exists('growth_notifications_v1020'))return [];$w=['tenant_id=?'];$p=[sk1020_tenant_id()];$uid=sk1020_user_id();if($uid>0){$w[]='user_id=?';$p[]=$uid;}else{$w[]='visitor_key=?';$p[]=sk1020_visitor_key();}try{$q=db()->prepare('SELECT * FROM growth_notifications_v1020 WHERE '.implode(' AND ',$w).' ORDER BY id DESC LIMIT '.max(1,min(30,$limit)));$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1020_admin_stats(int $days=7): array {$tid=sk1020_tenant_id();$cutoff=date('Y-m-d H:i:s',time()-max(1,$days)*86400);$out=['events'=>0,'visitors'=>0,'favorites'=>0,'follows'=>0,'no_results'=>0,'referrals'=>0,'points'=>0,'questions'=>0,'claims'=>0];try{if(sk1020_table_exists('visitor_events_v1020')){$q=db()->prepare('SELECT COUNT(*) c,COUNT(DISTINCT visitor_key) v,SUM(event_type=\'search\' AND COALESCE(result_count,0)=0) z FROM visitor_events_v1020 WHERE tenant_id=? AND created_at>=?');$q->execute([$tid,$cutoff]);$r=$q->fetch()?:[];$out['events']=(int)($r['c']??0);$out['visitors']=(int)($r['v']??0);$out['no_results']=(int)($r['z']??0);}foreach([['visitor_favorites_v1020','favorites'],['visitor_follows_v1020','follows'],['growth_questions_v1020','questions'],['growth_business_claims_v1020','claims']] as [$t,$k])if(sk1020_table_exists($t)){$q=db()->prepare('SELECT COUNT(*) FROM `'.$t.'` WHERE tenant_id=?');$q->execute([$tid]);$out[$k]=(int)$q->fetchColumn();}if(sk1020_table_exists('growth_referral_events_v1020')){$q=db()->prepare("SELECT COUNT(*) FROM growth_referral_events_v1020 WHERE tenant_id=? AND event_type='conversion'");$q->execute([$tid]);$out['referrals']=(int)$q->fetchColumn();}if(sk1020_table_exists('growth_rewards_ledger_v1020')){$q=db()->prepare('SELECT COALESCE(SUM(GREATEST(points,0)),0) FROM growth_rewards_ledger_v1020 WHERE tenant_id=?');$q->execute([$tid]);$out['points']=(int)$q->fetchColumn();}}catch(Throwable $e){}return $out; }
function sk1020_top_no_results(int $limit=12): array {if(!sk1020_table_exists('visitor_events_v1020'))return [];try{$q=db()->prepare("SELECT search_query,COUNT(*) searches FROM visitor_events_v1020 WHERE tenant_id=? AND event_type='search' AND COALESCE(result_count,0)=0 AND search_query<>'' AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY search_query ORDER BY searches DESC LIMIT ".max(1,min(50,$limit)));$q->execute([sk1020_tenant_id()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1020_top_searches(int $limit=12): array {if(!sk1020_table_exists('visitor_events_v1020'))return [];try{$q=db()->prepare("SELECT search_query,COUNT(*) searches FROM visitor_events_v1020 WHERE tenant_id=? AND event_type='search' AND search_query<>'' AND created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY search_query ORDER BY searches DESC LIMIT ".max(1,min(50,$limit)));$q->execute([sk1020_tenant_id()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
